Q: Bejeweled board generation A: <p>Once the board is generated, it is checked for matches. If a match is found, the tile type is changed. This continues until there are no matches. In the code, it could look like this:</p>
<pre><code>void Board::remove_match() {
    bool found = true;

    while (found) {
        found = false;
        for (int row = 0; row &lt; ROWS; row++) {// 8
            for (int col = 0; col &lt; COLS; col++) {// 8
            Piece *piece = get_piece(col, row);// from the previously created board
        int hcount = check_adjacent(col, row, 1, 0, piece-&gt;type, 1);
                int vcount = check_adjacent(col, row, 0, 1, piece-&gt;type, 1);
                if (hcount &gt;= 3 || vcount &gt;= 3) {
            found = true;
                bool matching = true;
            while (matching) {
            int type = rand() % piece_range;// 5 - 7
            if (piece-&gt;type != type) {
                    matching = false;
                piece-&gt;type = type;                 }
            }
           }
        }
    }
    } 
}
</code></pre>
<pre><code>int Board::check_adjacent(int col, int row, int hdir, int vdir, int type, int count)
{
    col += hdir;
    row += vdir;
    Piece *other = get_piece(col, row);

    if (other &amp;&amp; !other-&gt;is_moving &amp;&amp; other-&gt;type == type) {
    count += 1;
    count = check_adjacent(col, row, hdir, vdir, type, count);
    }
    return count;
}
</code></pre>
